L325: static enum scld_error safe_create_leading_directories_1(char *path, int share)
L326: {
L327: 	char *next_component = path + offset_1st_component(path);
L328: 	enum scld_error ret = SCLD_OK;
L329: 
L330: 	while (ret == SCLD_OK && next_component) {
L331: 		struct stat st;
L332: 		char *slash = next_component, slash_character;
L333: 
L334: 		while (*slash && !is_dir_sep(*slash))
L335: 			slash++;
L336: 
L337: 		if (!*slash)
L338: 			break;
L339: 
L340: 		next_component = slash + 1;
L341: 		while (is_dir_sep(*next_component))
L342: 			next_component++;
L343: 		if (!*next_component)
L344: 			break;
L345: 		slash_character = *slash;
L346: 		*slash = '\0';
L347: 		if (!stat(path, &st)) {
L348: 			/* path exists */
L349: 			if (!S_ISDIR(st.st_mode)) {
L350: 				errno = ENOTDIR;
L351: 				ret = SCLD_EXISTS;
L352: 			}
L353: 		} else if (mkdir(path, 0777)) {
L354: 			if (errno == EEXIST &&
L355: 			    !stat(path, &st) && S_ISDIR(st.st_mode))
L356: 				; /* somebody created it since we checked */
L357: 			else if (errno == ENOENT)
L358: 				/*
L359: 				 * Either mkdir() failed because
L360: 				 * somebody just pruned the containing
L361: 				 * directory, or stat() failed because
L362: 				 * the file that was in our way was
L363: 				 * just removed.  Either way, inform
L364: 				 * the caller that it might be worth
L365: 				 * trying again:
L366: 				 */
L367: 				ret = SCLD_VANISHED;
L368: 			else
L369: 				ret = SCLD_FAILED;
L370: 		} else if (share && adjust_shared_perm(path)) {
L371: 			ret = SCLD_PERMS;
L372: 		}
L373: 		*slash = slash_character;
L374: 	}
L375: 	return ret;
L376: }
