if (envchanged)

*envchanged = 1;

} else if (!strcmp(cmd, "--icase-pathspecs")) {

setenv(GIT_ICASE_PATHSPECS_ENVIRONMENT, "1", 1);

if (envchanged)

*envchanged = 1;

