static struct cmd_struct *get_builtin(const char *s)

{

for (size_t i = 0; i < ARRAY_SIZE(commands); i++) {

struct cmd_struct *p = commands + i;

if (!strcmp(s, p->cmd))

return p;

}

return NULL;

}

